@Test
public void testHandleRequestOK() throws Exception {
    String[] files = { "" };
    MyMergedLogSource mls = new MyMergedLogSource(files);
    final JsonServlet.JsonRequest jsonRequest = mock(JsonServlet.JsonRequest.class);
